<?php
$url=getenv('PUFFX_URL')?:'https://api.example.com';$key=getenv('PUFFX_API_KEY');if(!$key)throw new RuntimeException('Set PUFFX_API_KEY server-side');$ch=curl_init($url.'/v1/chat/completions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['messages'=>[['role'=>'user','content'=>'Hello']]])]);$body=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);if($body===false||$code>=400)throw new RuntimeException('HTTP/API failure: '.curl_error($ch));$data=json_decode($body,true,512,JSON_THROW_ON_ERROR);echo $data['choices'][0]['message']['content'];curl_close($ch);
